/**
 * Receives Dialer → agencyBRIDGE lifecycle events (spec §6). Authenticated
 * by the `X-MB-Signature` HMAC (not a Clerk session). Idempotent on
 * `eventId`; duplicate / out-of-order deliveries are deduped. Unknown
 * event `type` values and unknown fields are ignored (forward-compat,
 * §6.2). Every event lands in the agencyBRIDGE audit log.
 * @summary Inbound masterBRIDGE dialer lifecycle event (HMAC-signed webhook)
 */
export const PostDialerV1EventsHeader = zod.object({
  "X-MB-Signature": zod
    .string()
    .describe("t=<unixSeconds>,v1=<hex HMAC-SHA256 of `${t}.${rawBody}`>"),
});

export const PostDialerV1EventsBody = zod
  .object({
    eventId: zod
      .string()
      .describe("Unique event id; the receiver dedupes on this."),
    schemaVersion: zod
      .number()
      .int()
      .optional()
      .describe("Envelope schema version (currently 1)."),
    type: zod
      .string()
      .describe(
        "Event type. Known values include call.initiated, call.ringing,\ncall.in_progress, call.completed, call.failed,\ncall.disposition.recorded, call.transcript.ready,\ncall.transcript.purged, call.compliance.flagged. Unknown values\nare ignored.\n",
      ),
    occurredAt: zod.coerce.date().optional(),
    orgId: zod.string(),
    dialTicketId: zod.string().optional(),
    dialerCallId: zod.string().optional(),
    data: zod.record(zod.string(), zod.unknown()).optional(),
  })
  .describe(
    "Dialer → agencyBRIDGE event envelope (spec §6). Additional\/unknown\nproperties are permitted and ignored by consumers (forward-compat,\n§6.2), hence `additionalProperties: true`.\n",
  );

export const PostDialerV1EventsResponse = zod.object({
  status: zod.enum(["accepted", "ignored", "duplicate"]),
  eventId: zod.string(),
});

